# Bench 67: the page is polled ten times a second (not on every frame), the strip under the top panel blurs what lies under it, the editor has a look of its own.
from lib import *
p, br, pg, errs = start(1500, 950)
J = lambda s, a=None: pg.evaluate(s, a) if a is not None else pg.evaluate(s)
setup(pg)
J(BUILD); pg.wait_for_timeout(800)
J("""async()=>{const R=await import('/extensions/ComfyUI-NeuralDreamer-UI/ndui/render.js'); const P=R.PageView.prototype, o=P.sync; window.__sync=0; P.sync=function(){window.__sync++; return o.apply(this,arguments)}}""")
J("window.ndUi.enter()"); pg.wait_for_timeout(1500)
J("()=>{window.__sync=0}"); pg.wait_for_timeout(1500)
n = J("window.__sync")
check("the widgets are polled about ten times a second per page (not 60)", 6 <= n <= 36, str(n))
bf = J("()=>{const s=document.querySelector('.ndk-uimode .ndk-um-strip'); const c=getComputedStyle(s); return c.backdropFilter||c.webkitBackdropFilter}")
check("the strip under the top panel blurs what is under it", "blur" in str(bf), str(bf))
J("window.ndUi.exit()"); pg.wait_for_timeout(400)
# the look of the editor
L = "/extensions/ComfyUI-NeuralDreamer-UI/ndui/editor_look.js"
c = J("""async()=>{const M=await import('%s'); const a=M.cleanLook({accent:'#FF8800',top:'nope',dots:false,canvas:{type:'gradient',a:'#112233',b:'#445566',angle:999}}); return a}""" % L)
check("the look is cleaned", c["accent"] == "#ff8800" and c["top"] == "" and c["dots"] is False and c["canvas"]["angle"] == 360 and c["canvas"]["type"] == "gradient", str(c))
J("window.ndUi.host().openEditor()"); pg.wait_for_timeout(1500)
J("()=>document.querySelector('.nde-rtabs button[data-rtab=editor]').click()"); pg.wait_for_timeout(500)
labs = J("()=>[...document.querySelectorAll('.nde-right .nde-lab')].map(l=>l.textContent)")
check("the Editor tab: accent, side panels, top bar, canvas", all(x in labs for x in ["Accent", "Side panels", "Top bar", "Background"]), str(labs))
J("""async()=>{const M=await import('%s'); const E=window.ndUi.host().editor; Object.assign(E.look, M.cleanLook({accent:'#ff8800',side:'#202030',top:'#303040',canvas:{type:'gradient',a:'#112233',b:'#445566',angle:90}})); M.applyLook(E.root,E.look); E.renderInspector()}""" % L)
pg.wait_for_timeout(300)
v = J("""()=>{const r=document.querySelector('.nde'); const cs=getComputedStyle(r); return [cs.getPropertyValue('--ndk-accent').trim(), getComputedStyle(document.querySelector('.nde-left')).backgroundColor, getComputedStyle(document.querySelector('.nde-top')).backgroundColor, getComputedStyle(document.querySelector('.nde-center')).backgroundImage.includes('linear-gradient')]}""")
check("accent, side panels, top bar and the gradient canvas follow", v[0] == "#ff8800" and v[1] == "rgb(32, 32, 48)" and v[2] == "rgb(48, 48, 64)" and v[3] is True, str(v))
J("""async()=>{const M=await import('%s'); const E=window.ndUi.host().editor; Object.assign(E.look, M.cleanLook(null)); M.applyLook(E.root,E.look); E.renderInspector()}""" % L)
pg.wait_for_timeout(200)
v = J("""()=>{const cs=getComputedStyle(document.querySelector('.nde')); return [cs.getPropertyValue('--ndk-accent').trim(), cs.getPropertyValue('--ndk-accent-soft').trim(), cs.getPropertyValue('--ndk-on-accent').trim()]}""")
check("Back to the usual look: the accent goes back to the default, it does not vanish", v[0] != "" and v[0] != "#ff8800" and v[1] != "" and v[2] != "", str(v))
J("window.ndUi.host().editor?.close?.()"); pg.wait_for_timeout(300)
finish(p, br, errs)
